// Package auth implements the authentication handler for the application.
package auth

import (
	"context"

	"encore.dev/beta/auth"
	"encore.dev/beta/errs"
)

// AuthData is the custom authentication data returned by the auth handler.
type AuthData struct {
	Role string
}

// AuthHandler is the authentication handler.
//
// It validates the incoming token and returns the user's UID and custom auth data.
//
//encore:authhandler
func AuthHandler(ctx context.Context, token string) (auth.UID, *AuthData, error) {
	// Check if the token matches the expected secret token.
	if token == "secret-token" {
		// Return the user ID and custom auth data with the admin role.
		return auth.UID("user-123"), &AuthData{Role: "admin"}, nil
	}

	// If the token is invalid or missing, return an Unauthenticated error.
	return "", nil, &errs.Error{
		Code:    errs.Unauthenticated,
		Message: "invalid or missing token",
	}
}

// Package dashboard provides a protected API endpoint that requires authentication.
package dashboard

import (
	"context"

	"encore.dev/beta/auth"

	customauth "custom-auth-app/auth"
)

// Response is the JSON response returned by the dashboard endpoint.
type Response struct {
	Message string `json:"message"`
}

// GetDashboard is a protected API endpoint that requires authentication.
//
// It reads the authenticated user's ID and custom auth data from the context
// and returns a greeting message.
//
//encore:api auth
func GetDashboard(ctx context.Context) (*Response, error) {
	// Get the authenticated user's ID from the context.
	uid, _ := auth.UserID()

	// Get the custom auth data from the context and cast it to our custom type.
	data, ok := auth.Data().(*customauth.AuthData)

	// Build the greeting message using the user's ID and role.
	role := ""
	if ok {
		role = data.Role
	}

	return &Response{
		Message: "Hello " + string(uid) + ", you are an " + role,
	}, nil
}

